                                                  \usepackage{upgreek}
                                                  \setlength{\oddsidemargin}{-69pt}
                                                  \begin{document}$$\frac{D\rho }{Dt}=\frac{\partial (\Gamma \varepsilon {N}^{-2}\frac{\partial \rho }{\partial z})}{\partial z},$$\end{document}DρDt=∂(ΓεN−2∂ρ∂z)∂z,where, \documentclass[12pt]{minimal}
                                                  \usepackage{amsmath}
                                                  \usepackage{wasysym}
